<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- estimation tooltip disclaimer from game i18n */
  import { farmingMetrics } from '../stores/farmingMetrics.svelte.ts';

  let snap = $derived(farmingMetrics.snapshot);
  let showEstimationTip = $state(false);

  const DONUT_SIZE = 96;
  const DONUT_R = 36;
  const DONUT_CX = DONUT_SIZE / 2;
  const DONUT_CY = DONUT_SIZE / 2;
  const DONUT_STROKE = 14;
  const DONUT_C = 2 * Math.PI * DONUT_R;

  function donutSegments(slices: NonNullable<typeof snap>['donutSlices']) {
    let offset = 0;
    return slices.map((s) => {
      const total = slices.reduce((sum, x) => sum + x.value, 0);
      const frac = total > 0 ? s.value / total : 0;
      const len = DONUT_C * frac;
      const seg = {
        color: s.color,
        dasharray: `${len.toFixed(2)} ${(DONUT_C - len).toFixed(2)}`,
        dashoffset: (-offset).toFixed(2),
      };
      offset += len;
      return seg;
    });
  }

  function onCombatsTooltip(e: MouseEvent, row: { tooltipTitle?: string; tooltipLines?: string[] }) {
    const g = (globalThis as { game?: { scheduleTooltip?: (ev: MouseEvent, t: string, d: string, dly?: number) => void; hideTooltip?: () => void } }).game;
    if (!g?.scheduleTooltip || !row.tooltipTitle || !row.tooltipLines) return;
    g.scheduleTooltip(e, row.tooltipTitle, row.tooltipLines.join('<br>'), 50);
  }

  function hideTooltip() {
    (globalThis as { game?: { hideTooltip?: () => void } }).game?.hideTooltip?.();
  }
</script>

{#if snap}
<div class="stats-content js-modal-content farming-metrics-modal-content"
  data-action="stopPropagation" data-action-stop style="max-width: 420px; width: min(92vw, 420px);">
  <div class="stats-header">
    <h2 id="farmingMetricsModalTitle">&#128200; {snap.modalTitle}</h2>
    <button type="button" class="stats-close js-close-modal" data-action="closeFarmingMetricsModal">&#10005;</button>
  </div>
  <div class="farming-metrics-body">
    <div class="farming-metrics-toggle-row">
      <span class="farming-metrics-label" id="farmingMetricsRecordingLabel">{snap.recordingLabel}</span>
      <button type="button" id="farmingMetricsRecordingBtn" class="farming-metrics-toggle-btn"
        class:recording={snap.recording} data-action="toggleFarmingMetricsRecording">
        <span id="farmingMetricsRecordingText">{snap.recordingText}</span>
      </button>
    </div>
    <div class="farming-metrics-actions">
      <button type="button" id="farmingMetricsResetBtn" class="farming-metrics-reset-btn"
        data-action="resetFarmingMetricsAndRefresh">
        <span id="farmingMetricsResetLabel">{snap.resetLabel}</span>
      </button>
    </div>
    <div class="farming-metrics-period" id="farmingMetricsPeriodText">{snap.periodText}</div>
    <div class="farming-metrics-grid" id="farmingMetricsGrid">
      {#each snap.mainRows as row (row.label)}
        <div
          class="metric-row"
          class:metric-row-with-tooltip={row.withTooltip}
          role={row.withTooltip ? 'group' : undefined}
          onmouseenter={(e) => row.withTooltip && onCombatsTooltip(e, row)}
          onmouseleave={hideTooltip}
        >
          <span class="metric-label">
            {row.label}
            {#if row.withTooltip}
              <span class="metric-tooltip-hint" aria-hidden="true">?</span>
            {/if}
          </span>
          <span class="metric-value">{row.value}</span>
        </div>
      {/each}
    </div>

    {#if snap.avgVisible}
      <div class="farming-metrics-section" id="farmingMetricsAvgSection">
        <div class="farming-metrics-section-title" id="farmingMetricsAvgTitle">{snap.avgTitle}</div>
        <div class="farming-metrics-grid" id="farmingMetricsAvgGrid">
          {#each snap.avgRows as row (row.label)}
            <div class="metric-row">
              <span class="metric-label">{row.label}</span>
              <span class="metric-value">{row.value}</span>
            </div>
          {/each}
        </div>
      </div>
    {/if}

    {#if snap.dryVisible}
      <div class="farming-metrics-section" id="farmingMetricsDryStreakSection">
        <div class="farming-metrics-section-title" id="farmingMetricsDryStreakTitle">{snap.dryTitle}</div>
        <div class="farming-metrics-grid" id="farmingMetricsDryStreakGrid">
          {#each snap.dryRows as row (row.label)}
            <div class="metric-row">
              <span class="metric-label">{row.label}</span>
              <span class="metric-value">{row.value}</span>
            </div>
          {/each}
        </div>
      </div>
    {/if}

    {#if snap.revenueVisible}
      <div class="farming-metrics-section" id="farmingMetricsRevenueSection">
        <div class="farming-metrics-section-title" id="farmingMetricsRevenueTitle">{snap.revenueTitle}</div>
        <div class="farming-metrics-donut-row">
          <div class="farming-metrics-donut-svg" id="farmingMetricsDonutSvg">
            <svg viewBox="0 0 {DONUT_SIZE} {DONUT_SIZE}" width={DONUT_SIZE} height={DONUT_SIZE}>
              <circle cx={DONUT_CX} cy={DONUT_CY} r={DONUT_R} fill="none"
                stroke="rgba(15,23,42,0.18)" stroke-width={DONUT_STROKE} />
              {#each donutSegments(snap.donutSlices) as seg (seg.color)}
                <circle cx={DONUT_CX} cy={DONUT_CY} r={DONUT_R} fill="none"
                  stroke={seg.color} stroke-width={DONUT_STROKE}
                  stroke-dasharray={seg.dasharray} stroke-dashoffset={seg.dashoffset}
                  transform="rotate(-90 {DONUT_CX} {DONUT_CY})" />
              {/each}
            </svg>
          </div>
          <div class="farming-metrics-donut-legend" id="farmingMetricsDonutLegend">
            {#each snap.donutSlices as s (s.label)}
              <div class="farming-metrics-donut-legend-row">
                <span class="farming-metrics-donut-legend-swatch" style:background={s.color}></span>
                <span class="farming-metrics-donut-legend-label">{s.label}</span>
                <span class="farming-metrics-donut-legend-value">{Math.round(s.value)}$ ({s.percent}%)</span>
              </div>
            {/each}
          </div>
        </div>
      </div>
    {/if}

    {#if snap.topItemsVisible}
      <div class="farming-metrics-section" id="farmingMetricsTopItemsSection">
        <div class="farming-metrics-section-title" id="farmingMetricsTopItemsTitle">{snap.topItemsTitle}</div>
        <div class="farming-metrics-top-items" id="farmingMetricsTopItems">
          {#each snap.topItems as item (item.key)}
            <div class="farming-metrics-top-item">
              {#if item.img}
                <img src={item.img} alt="" class="farming-metrics-top-item-sprite" loading="lazy" decoding="async"
                  onerror={(e) => {
                    const img = e.currentTarget as HTMLImageElement;
                    img.style.display = 'none';
                    const icon = img.nextElementSibling as HTMLElement | null;
                    if (icon) icon.style.display = 'inline';
                  }} />
                <span class="farming-metrics-top-item-icon" style="display:none;">{item.icon}</span>
              {:else}
                <span class="farming-metrics-top-item-icon">{item.icon}</span>
              {/if}
              <span class="farming-metrics-top-item-name">{item.name}</span>
              <span class="farming-metrics-top-item-count">×{item.count}</span>
            </div>
          {/each}
        </div>
      </div>
    {/if}

    {#if snap.timelineVisible && snap.timeline}
      <div class="farming-metrics-section" id="farmingMetricsTimelineSection">
        <div class="farming-metrics-section-title" id="farmingMetricsTimelineTitle">{snap.timelineTitle}</div>
        <div class="farming-metrics-timeline" id="farmingMetricsTimelineSparkline">
          <div class="farming-metrics-timeline-wrap">
            <svg class="farming-metrics-timeline-svg" viewBox="0 0 280 56" preserveAspectRatio="none">
              <polyline points={snap.timeline.moneyPoints} fill="none" stroke="#10b981" stroke-width="1.4" />
              <polyline points={snap.timeline.xpPoints} fill="none" stroke="#3b82f6" stroke-width="1.4"
                stroke-dasharray="2 2" />
            </svg>
            <div class="farming-metrics-timeline-legend">
              <span><span class="farming-metrics-timeline-swatch" style="background:#10b981"></span>$
                {snap.timeline.totalMoney}</span>
              <span><span class="farming-metrics-timeline-swatch" style="background:#3b82f6"></span>XP
                {snap.timeline.totalXp}</span>
              <span class="farming-metrics-timeline-window">{snap.timeline.windowLabel}</span>
            </div>
          </div>
        </div>
      </div>
    {/if}

    <div class="farming-metrics-item-select-row">
      <label for="farmingMetricsItemSelect" class="farming-metrics-label" id="farmingMetricsItemSelectLabel">{snap.itemSelectLabel}</label>
      <select id="farmingMetricsItemSelect" class="farming-metrics-item-select">
        {#each snap.itemOptions as opt (opt.value)}
          <option value={opt.value}>{opt.label}</option>
        {/each}
      </select>
    </div>

    <div class="farming-metrics-estimation-mode-row">
      <span class="farming-metrics-label" id="farmingMetricsEstimationModeLabel">{snap.estimationModeLabel}</span>
      <div class="farming-metrics-estimation-mode-tabs">
        <button type="button" id="farmingMetricsEstimationModeForward"
          class="farming-metrics-mode-tab" class:active={snap.estimationMode === 'forward'}
          data-action="setFarmingEstimationMode" data-arg="forward">{snap.estimationModeForwardLabel}</button>
        <button type="button" id="farmingMetricsEstimationModeGoal"
          class="farming-metrics-mode-tab" class:active={snap.estimationMode === 'goal'}
          data-action="setFarmingEstimationMode" data-arg="goal">{snap.estimationModeGoalLabel}</button>
      </div>
    </div>

    {#if snap.estimationMode === 'forward'}
      <div
        class="farming-metrics-estimation-row"
        id="farmingMetricsEstimationRow"
        role="group"
        onmouseenter={() => { showEstimationTip = true; }}
        onmouseleave={() => { showEstimationTip = false; }}
      >
        <label for="farmingMetricsEstimationSelect" class="farming-metrics-label" id="farmingMetricsEstimationLabel">
          {@html snap.estimationLabelHtml}
        </label>
        <select id="farmingMetricsEstimationSelect" class="farming-metrics-item-select">
          {#each snap.estimationOptions as opt (opt.value)}
            <option value={opt.value}>{opt.label}</option>
          {/each}
        </select>
        <div
          class="farming-metrics-estimation-tooltip"
          class:show={showEstimationTip}
          id="farmingMetricsEstimationTooltip"
          role="tooltip"
        >
          {@html snap.estimationTooltipHtml}
        </div>
      </div>
    {:else}
      <fieldset class="farming-metrics-estimation-row farming-metrics-fieldset" id="farmingMetricsGoalRow">
        <legend class="farming-metrics-label" id="farmingMetricsGoalLabel">{snap.goalLabel}</legend>
        <select id="farmingMetricsGoalMetricSelect" class="farming-metrics-item-select"
          data-action="setFarmingGoalMetric" value={snap.goalMetric}>
          {#each snap.goalOptions as opt (opt.value)}
            <option value={opt.value}>{opt.label}</option>
          {/each}
        </select>
        <input type="number" id="farmingMetricsGoalAmountInput" class="farming-metrics-goal-input"
          min="1" step="1000" data-action-on-change="setFarmingGoalAmount" value={snap.goalAmount} />
        <div class="farming-metrics-goal-result" id="farmingMetricsGoalResult">
          {@html snap.goalResultHtml}
        </div>
      </fieldset>
    {/if}

    <div class="farming-metrics-section" id="farmingMetricsSessionsSection">
      <div class="farming-metrics-section-title" id="farmingMetricsSessionsTitle">{snap.sessionsTitle}</div>
      <div class="farming-metrics-sessions-actions">
        <input type="text" id="farmingMetricsSessionNameInput" class="farming-metrics-session-name-input"
          placeholder={snap.sessionNamePlaceholder} maxlength="40" />
        <button type="button" id="farmingMetricsSaveSessionBtn" class="farming-metrics-save-session-btn"
          data-action="saveFarmingSessionFromInput">{snap.sessionsSaveLabel}</button>
      </div>
      <div class="farming-metrics-sessions-list" id="farmingMetricsSessionsList">
        {#if snap.sessions.length === 0}
          <div class="farming-metrics-sessions-empty">{snap.sessionsEmpty}</div>
        {:else}
          {#each snap.sessions as session (session.index)}
            <div class="farming-metrics-session-row">
              <div class="farming-metrics-session-name">{session.name}</div>
              <div class="farming-metrics-session-stats">
                <span>{session.money}</span>
                <span>{session.xp}</span>
                <span>{session.combats}</span>
                <span>{session.duration}</span>
              </div>
              <button type="button" class="farming-metrics-session-delete"
                data-action="deleteFarmingSession" data-arg={String(session.index)} title={snap.deleteSessionTitle}>×</button>
            </div>
          {/each}
        {/if}
      </div>
    </div>
  </div>
</div>
{/if}
